import { StrictMode } from 'react';
import { createRoot }  from 'react-dom/client';
import { Amplify }     from 'aws-amplify';
import './index.css';
import App from './App.tsx';
import { registerServiceWorker } from './utils/reminders';

// amplify_outputs.json is generated by the CI pipeline (via `ampx generate outputs`)
// or locally by `npx ampx sandbox`. It is gitignored and only exists when the
// backend has been deployed. AMPLIFY_OUTPUTS is injected by vite.config.ts as a
// JSON string so the build never fails even when the file is absent.
declare const __AMPLIFY_OUTPUTS__: string;

try {
  const raw: string = typeof __AMPLIFY_OUTPUTS__ !== 'undefined' ? __AMPLIFY_OUTPUTS__ : '{}';
  const outputs = JSON.parse(raw);
  const url: string = outputs?.data?.url ?? '';
  if (url && !url.startsWith('REPLACE')) {
    Amplify.configure(outputs);
    console.info('[PrayTogether] Amplify configured ✅');
  } else {
    console.warn('[PrayTogether] amplify_outputs.json missing or has placeholder values — cloud inactive.');
  }
} catch (e) {
  console.warn('[PrayTogether] Failed to configure Amplify', e);
}

// Register the service worker for push notifications
registerServiceWorker();

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App />
  </StrictMode>,
);
